import {createChatOrchestrator} from './chatOrchestrator.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import {createMockProvider} from '../providers/mock/mockProvider.js';
import type {ChatSession} from '../types/session.js';

// spec: specs/hal-engine-config-hooks/spec.md#7
it('cleans up a partially initialized turn before rejecting with the startup error', async () => {
  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
  const failure = new Error('startup failed');
  const events: string[] = [];
  let allocated = false;
  const orchestrator = createChatOrchestrator(createMockProvider(), new PromptBuilder({identity: 'test'}), undefined, {
    hooks: {
      beforeSession: async () => {
        allocated = true;
        throw failure;
      },
      onError: async (current, error) => {
        if (current === session && error === failure) events.push('error');
      },
      afterSession: async current => {
        if (current === session && allocated) events.push('cleanup');
        allocated = false;
      },
    },
  });

  const rejected = await orchestrator.processMessage(session).catch((error: unknown) => error);

  expect({sameError: rejected === failure, events, allocated}).toEqual({
    sameError: true,
    events: ['error', 'cleanup'],
    allocated: false,
  });
});
EOF
timeout 300 npm test -- --runTestsByPath src/orchestration/chatOrchestrator.startup.test.ts --runInBand"
